function evalRPN(tokens) {
  const items = tokens.slice();
  function isOp(token) {
    return token === '+' || token === '-' || token === '*' || token === '/';
  }
  while (items.length > 1) {
    let opIdx = -1;
    for (let i = 0; i < items.length; i++) {
      if (isOp(items[i])) {
        opIdx = i;
        break;
      }
    }
    if (opIdx < 1) {
      break;
    }
    const a = Number(items[opIdx - 2]);
    const b = Number(items[opIdx - 1]);
    const op = items[opIdx];
    let value = 0;
    if (op === '+') {
      value = a + b;
    } else if (op === '-') {
      value = a - b;
    } else if (op === '*') {
      value = a * b;
    } else {
      value = Math.trunc(a / b);
    }
    items.splice(opIdx - 2, 3, String(value));
  }
  return Number(items[items.length - 1]);
}

function evalRPN(tokens) {
  const stack = [];
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (token === '+' || token === '-' || token === '*' || token === '/') {
      const b = stack.length > 0 ? stack.pop() : 0;
      const a = stack.length > 0 ? stack.pop() : 0;
      let value = 0;
      if (token === '+') {
        value = a + b;
      } else if (token === '-') {
        value = a - b;
      } else if (token === '*') {
        value = a * b;
      } else {
        value = Math.trunc(a / b);
      }
      stack.push(value);
    } else {
      stack.push(Number(token));
    }
  }
  return stack.pop();
}
